<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Expense Tracker</title>
    <style>
        :root {
            --primary: #2563eb;
            --danger: #dc2626;
            --bg: #f8fafc;
            --card: #ffffff;
            --text: #1e293b;
        }

        body {
            font-family: system-ui, -apple-system, sans-serif;
            background-color: var(--bg);
            color: var(--text);
            margin: 0;
            display: flex;
            justify-content: center;
            padding: 20px;
        }

        .container {
            width: 100%;
            max-width: 500px;
            background: var(--card);
            padding: 2rem;
            border-radius: 8px;
            box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
        }

        h2 { margin-top: 0; font-size: 1.5rem; }

        .form-group { margin-bottom: 1rem; }
        label { display: block; font-size: 0.875rem; font-weight: 600; margin-bottom: 4px; }

        input, select {
            width: 100%;
            padding: 8px;
            border: 1px solid #cbd5e1;
            border-radius: 4px;
            box-sizing: border-box;
            font-size: 1rem;
        }

        button {
            cursor: pointer;
            padding: 10px 15px;
            border: none;
            border-radius: 4px;
            font-weight: 600;
        }

        #add-expense {
            width: 100%;
            background-color: var(--primary);
            color: white;
        }

        #form-error {
            color: var(--danger);
            font-size: 0.875rem;
            min-height: 1.25rem;
            margin-bottom: 1rem;
        }

        .filters {
            background: #f1f5f9;
            padding: 1rem;
            border-radius: 4px;
            margin: 1.5rem 0;
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .filter-row {
            display: flex;
            gap: 10px;
        }

        .summary {
            margin: 1.5rem 0;
            padding-top: 1rem;
            border-top: 2px solid #e2e8f0;
        }

        .total-display {
            font-size: 1.25rem;
            font-weight: bold;
            margin-bottom: 0.5rem;
        }

        .cat-summary-list {
            font-size: 0.875rem;
            color: #64748b;
        }

        .expense-list {
            margin-top: 1.5rem;
        }

        .expense {
            display: grid;
            grid-template-columns: 1fr 1fr 1fr auto;
            gap: 10px;
            align-items: center;
            padding: 10px 0;
            border-bottom: 1px solid #e2e8f0;
            font-size: 0.9rem;
        }

        .exp-amt { font-weight: 600; }
        .exp-del {
            background: #fee2e2;
            color: var(--danger);
            font-size: 0.75rem;
            padding: 4px 8px;
        }
        .exp-del:hover { background: #fecaca; }
    </style>
</head>
<body>

<div class="container">
    <h2>Add Expense</h2>
    <form id="expense-form">
        <div id="form-error"></div>
        <div class="form-group">
            <label for="amount">Amount</label>
            <input type="number" id="amount" step="0.01" placeholder="0.00">
        </div>
        <div class="form-group">
            <label for="category">Category</label>
            <select id="category">
                <option value="groceries">groceries</option>
                <option value="transport">transport</option>
                <option value="bills">bills</option>
                <option value="fun">fun</option>
            </select>
        </div>
        <div class="form-group">
            <label for="date">Date</label>
            <input type="date" id="date">
        </div>
        <div class="form-group">
            <label for="note">Note (Optional)</label>
            <input type="text" id="note">
        </div>
        <button type="button" id="add-expense">Add Expense</button>
    </form>

    <div class="filters">
        <label>Filters</label>
        <select id="filter-category">
            <option value="all">All Categories</option>
            <option value="groceries">groceries</option>
            <option value="transport">transport</option>
            <option value="bills">bills</option>
            <option value="fun">fun</option>
        </select>
        <div class="filter-row">
            <input type="date" id="filter-from" aria-label="Filter from date">
            <input type="date" id="filter-to" aria-label="Filter to date">
        </div>
    </div>

    <div class="summary">
        <div class="total-display">Total: $<span id="total">0.00</span></div>
        <div class="cat-summary-list">
            <div class="cat-total" data-cat="groceries">groceries: 0.00</div>
            <div class="cat-total" data-cat="transport">transport: 0.00</div>
            <div class="cat-total" data-cat="bills">bills: 0.00</div>
            <div class="cat-total" data-cat="fun">fun: 0.00</div>
        </div>
    </div>

    <div class="expense-list" id="expense-list"></div>
</div>

<script>
    // State
    let expenses = JSON.parse(localStorage.getItem('expenses_data')) || [];

    // DOM Elements
    const form = document.getElementById('expense-form');
    const amountInput = document.getElementById('amount');
    const categoryInput = document.getElementById('category');
    const dateInput = document.getElementById('date');
    const noteInput = document.getElementById('note');
    const errorEl = document.getElementById('form-error');
    const addBtn = document.getElementById('add-expense');

    const listContainer = document.getElementById('expense-list');
    const totalEl = document.getElementById('total');

    const filterCat = document.getElementById('filter-category');
    const filterFrom = document.getElementById('filter-from');
    const filterTo = document.getElementById('filter-to');

    // Logic
    function save() {
        localStorage.setItem('expenses_data', JSON.stringify(expenses));
    }

    function addExpense() {
        const val = parseFloat(amountInput.value);
        const date = dateInput.value;

        if (!date || isNaN(val) || val <= 0) {
            errorEl.textContent = "Invalid amount or missing date.";
            return;
        }

        const newExpense = {
            id: Date.now(),
            amount: val,
            category: categoryInput.value,
            date: date,
            note: noteInput.value
        };

        expenses.push(newExpense);
        save();
        render();

        // Reset
        errorEl.textContent = "";
        amountInput.value = "";
        dateInput.value = "";
        noteInput.value = "";
    }

    function deleteExpense(id) {
        expenses = expenses.filter(e => e.id !== id);
        save();
        render();
    }

    function render() {
        listContainer.innerHTML = '';

        // Apply Filters
        const fCat = filterCat.value;
        const fFrom = filterFrom.value;
        const fTo = filterTo.value;

        let filtered = expenses.filter(e => {
            const matchCat = (fCat === 'all' || e.category === fCat);
            const matchFrom = !fFrom || e.date >= fFrom;
            const matchTo = !fTo || e.date <= fTo;
            return matchCat && matchFrom && matchTo;
        });

        // Sort Newest First
        filtered.sort((a, b) => new Date(b.date) - new Date(a.date));

        // Calculate totals
        let runningTotal = 0;
        const catTotals = { groceries: 0, transport: 0, bills: 0, fun: 0 };

        filtered.forEach(e => {
            runningTotal += e.amount;
            catTotals[e.category] += e.amount;

            const row = document.createElement('div');
            row.className = 'expense';
            row.innerHTML = `
                <span class="exp-amt">${e.amount.toFixed(2)}</span>
                <span class="exp-cat">${e.category}</span>
                <span class="exp-date">${e.date}</span>
                <button class="exp-del" data-id="${e.id}">Delete</button>
            `;
            listContainer.appendChild(row);
        });

        // Update UI
        totalEl.textContent = runningTotal.toFixed(2);
        document.querySelectorAll('.cat-total').forEach(el => {
            const cat = el.getAttribute('data-cat');
            el.textContent = `${cat}: ${catTotals[cat].toFixed(2)}`;
        });
    }

    // Events
    addBtn.addEventListener('click', addExpense);

    listContainer.addEventListener('click', (e) => {
        if (e.target.classList.contains('exp-del')) {
            const id = Number(e.target.getAttribute('data-id'));
            deleteExpense(id);
        }
    });

    [filterCat, filterFrom, filterTo].forEach(el => {
        el.addEventListener('change', render);
    });

    // Init
    render();
</script>

</body>
</html>
